PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?film ?filmLabel ?director ?directorLabel ?deathDate
WHERE {
  VALUES ?film { dbr:Raiders_of_Red_Gap dbr:A_Day_of_Fury }

  # director (prefer dbp:director)
  { ?film dbp:director ?director . }
  UNION
  { ?film dbo:director ?director . }

  # director death date (prefer dbp:deathDate)
  OPTIONAL { ?director dbp:deathDate ?deathDate1 . }
  OPTIONAL { ?director dbo:deathDate ?deathDate2 . }
  BIND (COALESCE(?deathDate1, ?deathDate2) AS ?deathDate)

  # optional English labels for readability
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER (lang(?directorLabel) = "en") }
}
LIMIT 100
